namespace BatchRenameStudio.Core;

/// <summary>Widget type used by the GUI editor and by the JSON reader/writer.</summary>
public enum FieldKind
{
    Text,
    Int,
    Bool,
    Choice
}

/// <summary>One editable parameter of one operation.</summary>
public sealed class FieldSpec
{
    public string Key { get; init; }
    public string Label { get; init; }
    public FieldKind Kind { get; init; }
    public object Default { get; init; }
    public string[] Choices { get; init; } = Array.Empty<string>();
    public int Min { get; init; } = -1_000_000;
    public int Max { get; init; } = 1_000_000;
    public string Hint { get; init; } = "";
}

/// <summary>Declarative description of one of the 14 operations.</summary>
public sealed class OpSpec
{
    public string Op { get; init; }
    public string Title { get; init; }
    public string Summary { get; init; }
    public FieldSpec[] Fields { get; init; } = Array.Empty<FieldSpec>();

    public FieldSpec Field(string key)
    {
        foreach (var f in Fields)
        {
            if (string.Equals(f.Key, key, StringComparison.Ordinal)) return f;
        }
        return null;
    }
}

/// <summary>
/// Single source of truth for the operation set. The engine, the JSON reader/writer and
/// the GUI property editor are all generated from this table, so a step can never be
/// editable in the GUI but unknown to the engine (or vice versa).
/// </summary>
public static class OpCatalog
{
    public const string OpReplace = "replace";
    public const string OpInsert = "insert";
    public const string OpRemove = "remove";
    public const string OpSequence = "sequence";
    public const string OpCase = "case";
    public const string OpExtension = "extension";
    public const string OpPad = "pad";
    public const string OpTrim = "trim";
    public const string OpSlug = "slug";
    public const string OpTranslate = "translate";
    public const string OpNumberFormat = "numberFormat";
    public const string OpExtract = "extract";
    public const string OpTemplate = "template";
    public const string OpDedupeChars = "dedupeChars";

    public static readonly OpSpec[] All =
    {
        new OpSpec
        {
            Op = OpReplace,
            Title = "Replace",
            Summary = "Replace every occurrence of a literal or regex pattern.",
            Fields = new[]
            {
                new FieldSpec { Key = "find", Label = "Find", Kind = FieldKind.Text, Default = "", Hint = "Empty = no-op." },
                new FieldSpec { Key = "replaceWith", Label = "Replace with", Kind = FieldKind.Text, Default = "", Hint = "Regex mode: $1 refers to group 1." },
                new FieldSpec { Key = "regex", Label = "Regex", Kind = FieldKind.Bool, Default = false },
                new FieldSpec { Key = "ignoreCase", Label = "Ignore case", Kind = FieldKind.Bool, Default = false }
            }
        },
        new OpSpec
        {
            Op = OpInsert,
            Title = "Insert",
            Summary = "Insert literal text at the start, the end or a 0-based index.",
            Fields = new[]
            {
                new FieldSpec { Key = "text", Label = "Text", Kind = FieldKind.Text, Default = "" },
                new FieldSpec { Key = "position", Label = "Position", Kind = FieldKind.Choice, Default = "prefix", Choices = new[] { "prefix", "suffix", "index" } },
                new FieldSpec { Key = "index", Label = "Index", Kind = FieldKind.Int, Default = 0, Min = 0, Max = 100000, Hint = "Used when position = index. Clamped to [0, length]." }
            }
        },
        new OpSpec
        {
            Op = OpRemove,
            Title = "Remove",
            Summary = "Delete a character range.",
            Fields = new[]
            {
                new FieldSpec { Key = "from", Label = "From", Kind = FieldKind.Int, Default = 0, Min = 0, Max = 100000, Hint = "0-based, clamped to [0, length]." },
                new FieldSpec { Key = "count", Label = "Count", Kind = FieldKind.Int, Default = 1, Min = 0, Max = 100000, Hint = "Clamped to what remains." }
            }
        },
        new OpSpec
        {
            Op = OpSequence,
            Title = "Sequence number",
            Summary = "Add a running number built from a pattern such as {n:000}_.",
            Fields = new[]
            {
                new FieldSpec { Key = "pattern", Label = "Pattern", Kind = FieldKind.Text, Default = "{n:000}_", Hint = "Literal text plus exactly one {n:000} token." },
                new FieldSpec { Key = "start", Label = "Start", Kind = FieldKind.Int, Default = 1, Min = 0, Max = 1000000 },
                new FieldSpec { Key = "step", Label = "Step", Kind = FieldKind.Int, Default = 1, Min = -100000, Max = 100000 },
                new FieldSpec { Key = "position", Label = "Position", Kind = FieldKind.Choice, Default = "prefix", Choices = new[] { "prefix", "suffix" } }
            }
        },
        new OpSpec
        {
            Op = OpCase,
            Title = "Case",
            Summary = "Upper-case, lower-case or title-case the target.",
            Fields = new[]
            {
                new FieldSpec { Key = "mode", Label = "Mode", Kind = FieldKind.Choice, Default = "upper", Choices = new[] { "upper", "lower", "title" } }
            }
        },
        new OpSpec
        {
            Op = OpExtension,
            Title = "Extension",
            Summary = "Change the file extension only.",
            Fields = new[]
            {
                new FieldSpec { Key = "mode", Label = "Mode", Kind = FieldKind.Choice, Default = "lower", Choices = new[] { "lower", "upper", "set" } },
                new FieldSpec { Key = "value", Label = "Value", Kind = FieldKind.Text, Default = "txt", Hint = "Used when mode = set. No leading dot." }
            }
        },
        new OpSpec
        {
            Op = OpPad,
            Title = "Pad",
            Summary = "Pad the target up to a fixed length with a single fill character.",
            Fields = new[]
            {
                new FieldSpec { Key = "length", Label = "Length", Kind = FieldKind.Int, Default = 10, Min = 0, Max = 255 },
                new FieldSpec { Key = "fill", Label = "Fill", Kind = FieldKind.Text, Default = "_", Hint = "Must be exactly one character, otherwise no-op." },
                new FieldSpec { Key = "side", Label = "Side", Kind = FieldKind.Choice, Default = "left", Choices = new[] { "left", "right" } }
            }
        },
        new OpSpec
        {
            Op = OpTrim,
            Title = "Trim",
            Summary = "Strip characters from the edges while they belong to a set.",
            Fields = new[]
            {
                new FieldSpec { Key = "chars", Label = "Characters", Kind = FieldKind.Text, Default = " _-", Hint = "Set of characters; empty = no-op." },
                new FieldSpec { Key = "side", Label = "Side", Kind = FieldKind.Choice, Default = "both", Choices = new[] { "both", "left", "right" } }
            }
        },
        new OpSpec
        {
            Op = OpSlug,
            Title = "Slug",
            Summary = "Lower-case and reduce to [a-z0-9] separated groups.",
            Fields = new[]
            {
                new FieldSpec { Key = "separator", Label = "Separator", Kind = FieldKind.Text, Default = "-", Hint = "Empty = drop the runs entirely." }
            }
        },
        new OpSpec
        {
            Op = OpTranslate,
            Title = "Translate characters",
            Summary = "Map characters one-to-one; unmapped tail characters are deleted.",
            Fields = new[]
            {
                new FieldSpec { Key = "from", Label = "From", Kind = FieldKind.Text, Default = "" },
                new FieldSpec { Key = "to", Label = "To", Kind = FieldKind.Text, Default = "", Hint = "Shorter than From = those characters are deleted." }
            }
        },
        new OpSpec
        {
            Op = OpNumberFormat,
            Title = "Number format",
            Summary = "Zero-pad the first run of digits to a fixed width.",
            Fields = new[]
            {
                new FieldSpec { Key = "width", Label = "Width", Kind = FieldKind.Int, Default = 4, Min = 0, Max = 255 }
            }
        },
        new OpSpec
        {
            Op = OpExtract,
            Title = "Extract",
            Summary = "Keep only the first regex match (or one of its groups).",
            Fields = new[]
            {
                new FieldSpec { Key = "pattern", Label = "Pattern", Kind = FieldKind.Text, Default = "\\d+" },
                new FieldSpec { Key = "group", Label = "Group", Kind = FieldKind.Int, Default = 0, Min = 0, Max = 99, Hint = "0 = the whole match. No match = empty target." }
            }
        },
        new OpSpec
        {
            Op = OpTemplate,
            Title = "Template",
            Summary = "Rebuild the target from {name} {ext} {len} {n:000}.",
            Fields = new[]
            {
                new FieldSpec { Key = "format", Label = "Format", Kind = FieldKind.Text, Default = "{name}-{ext}-{n:000}", Hint = "Unknown {tokens} are kept literally." }
            }
        },
        new OpSpec
        {
            Op = OpDedupeChars,
            Title = "Dedupe characters",
            Summary = "Collapse each run of the same character to one occurrence.",
            Fields = Array.Empty<FieldSpec>()
        }
    };

    public static OpSpec Find(string op)
    {
        if (op == null) return null;
        foreach (var spec in All)
        {
            if (string.Equals(spec.Op, op, StringComparison.Ordinal)) return spec;
        }
        return null;
    }

    public static bool IsKnown(string op) => Find(op) != null;
}

