using System.Globalization;
using System.Text;

namespace BatchRenameStudio.Core;

/// <summary>
/// One step of a rule set. Parameters live in a small property bag keyed by the
/// <see cref="OpCatalog"/> field names, which keeps JSON round-tripping, the GUI editor
/// and the engine in lock-step without 14 near-identical classes.
/// </summary>
public sealed class RuleStep
{
    public string Op { get; private set; }

    /// <summary>GUI-only convenience: unchecked steps are not exported and not applied.</summary>
    public bool Enabled { get; set; } = true;

    private readonly Dictionary<string, object> _values = new(StringComparer.Ordinal);

    private RuleStep(string op)
    {
        Op = op;
    }

    public static RuleStep Create(string op)
    {
        var spec = OpCatalog.Find(op) ?? throw new ArgumentException("Unknown operation: " + op, nameof(op));
        var step = new RuleStep(spec.Op);
        foreach (var f in spec.Fields)
        {
            step._values[f.Key] = f.Default;
        }
        return step;
    }

    public OpSpec Spec => OpCatalog.Find(Op);

    public RuleStep Clone()
    {
        var copy = new RuleStep(Op) { Enabled = Enabled };
        foreach (var kv in _values) copy._values[kv.Key] = kv.Value;
        return copy;
    }

    public void Set(string key, object value) => _values[key] = value;

    public string GetString(string key)
    {
        if (_values.TryGetValue(key, out var v) && v != null)
        {
            if (v is string s) return s;
            if (v is bool b) return b ? "true" : "false";
            return Convert.ToString(v, CultureInfo.InvariantCulture) ?? "";
        }
        var def = Spec?.Field(key)?.Default;
        return def as string ?? "";
    }

    public int GetInt(string key)
    {
        if (_values.TryGetValue(key, out var v) && v != null)
        {
            if (v is int i) return i;
            if (v is long l) return (int)l;
            if (v is double d) return (int)d;
            if (v is string s && int.TryParse(s, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed)) return parsed;
        }
        var def = Spec?.Field(key)?.Default;
        return def is int di ? di : 0;
    }

    public bool GetBool(string key)
    {
        if (_values.TryGetValue(key, out var v) && v != null)
        {
            if (v is bool b) return b;
            if (v is string s && bool.TryParse(s, out var parsed)) return parsed;
            if (v is int i) return i != 0;
        }
        var def = Spec?.Field(key)?.Default;
        return def is bool db && db;
    }

    /// <summary>A choice field falls back to its default when the JSON carries an unknown value.</summary>
    public string GetChoice(string key)
    {
        var spec = Spec?.Field(key);
        var raw = GetString(key);
        if (spec == null) return raw;
        foreach (var c in spec.Choices)
        {
            if (string.Equals(c, raw, StringComparison.OrdinalIgnoreCase)) return c;
        }
        return spec.Default as string ?? raw;
    }

    /// <summary>Short one-line description used in the GUI rule list.</summary>
    public string Describe()
    {
        var spec = Spec;
        if (spec == null) return Op;
        var sb = new StringBuilder(spec.Title);
        var parts = new List<string>();
        foreach (var f in spec.Fields)
        {
            switch (f.Kind)
            {
                case FieldKind.Bool:
                    if (GetBool(f.Key)) parts.Add(f.Key);
                    break;
                case FieldKind.Int:
                    parts.Add(f.Key + "=" + GetInt(f.Key).ToString(CultureInfo.InvariantCulture));
                    break;
                default:
                    parts.Add(f.Key + "=\"" + GetString(f.Key) + "\"");
                    break;
            }
        }
        if (parts.Count > 0)
        {
            sb.Append("  (").Append(string.Join(", ", parts)).Append(')');
        }
        return sb.ToString();
    }
}

