using System.Text;

namespace BatchRenameStudio.Core;

/// <summary>File-level helpers that guarantee UTF-8 without a byte-order mark.</summary>
public static class JsonIo
{
    /// <summary>UTF-8, no BOM, throws on invalid surrogates rather than silently emitting U+FFFD.</summary>
    public static readonly UTF8Encoding Utf8NoBom = new(encoderShouldEmitUTF8Identifier: false, throwOnInvalidBytes: false);

    public static void WriteTextUtf8NoBom(string path, string text)
    {
        var dir = Path.GetDirectoryName(Path.GetFullPath(path));
        if (!string.IsNullOrEmpty(dir) && !Directory.Exists(dir))
        {
            Directory.CreateDirectory(dir);
        }
        var bytes = Utf8NoBom.GetBytes(text);
        File.WriteAllBytes(path, bytes);
    }
}

