namespace BatchRenameStudio.Core;

/// <summary>
/// The literal name algebra of the specification: how a file name splits into base+ext,
/// how it is put back together, and what makes a proposed name invalid on Windows.
/// </summary>
public static class NameRules
{
    public const int MaxNameLength = 255;

    /// <summary>Characters Windows forbids in a file name component.</summary>
    private static readonly char[] ForbiddenChars = { '<', '>', ':', '"', '/', '\\', '|', '?', '*' };

    private static readonly HashSet<string> ReservedBaseNames = BuildReserved();

    private static HashSet<string> BuildReserved()
    {
        var set = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "CON", "PRN", "AUX", "NUL" };
        for (var i = 1; i <= 9; i++)
        {
            set.Add("COM" + i.ToString(System.Globalization.CultureInfo.InvariantCulture));
            set.Add("LPT" + i.ToString(System.Globalization.CultureInfo.InvariantCulture));
        }
        return set;
    }

    /// <summary>
    /// Rule 2. dot = index of the LAST '.'; when dot &gt; 0 the name splits there and the
    /// extension carries no dot. Otherwise the whole name is the base (so ".gitignore"
    /// has base ".gitignore" and an empty extension).
    /// </summary>
    public static void Split(string name, out string baseName, out string ext)
    {
        var dot = name.LastIndexOf('.');
        if (dot > 0)
        {
            baseName = name.Substring(0, dot);
            ext = name.Substring(dot + 1);
        }
        else
        {
            baseName = name;
            ext = "";
        }
    }

    /// <summary>Rule 6. base + "." + ext when ext is non-empty, otherwise base alone.</summary>
    public static string Join(string baseName, string ext) => ext.Length == 0 ? baseName : baseName + "." + ext;

    /// <summary>Rule 7, first bullet. Returns true and a short reason when the name cannot be used.</summary>
    public static bool IsInvalid(string proposed, out string reason)
    {
        if (proposed == null || proposed.Length == 0)
        {
            reason = "empty name";
            return true;
        }
        if (proposed.Length > MaxNameLength)
        {
            reason = "longer than " + MaxNameLength + " characters";
            return true;
        }
        foreach (var c in proposed)
        {
            if (c < ' ')
            {
                reason = "contains a control character (U+" + ((int)c).ToString("X4") + ")";
                return true;
            }
            foreach (var bad in ForbiddenChars)
            {
                if (c == bad)
                {
                    reason = "contains the reserved character '" + c + "'";
                    return true;
                }
            }
        }
        Split(proposed, out var baseName, out _);
        if (ReservedBaseNames.Contains(baseName))
        {
            reason = "'" + baseName + "' is a reserved device name";
            return true;
        }
        reason = "";
        return false;
    }
}

