using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>Mutable state of one file while its steps run.</summary>
public sealed class StepContext
{
    /// <summary>The string the steps operate on (rule 3).</summary>
    public string Target;

    /// <summary>Live extension. Only meaningful under applyTo = "name".</summary>
    public string Ext;

    /// <summary>Rule-2 extension of the original file name; what {ext} in a template resolves to.</summary>
    public string OriginalExt;

    /// <summary>0-based position in processing order (rule 5).</summary>
    public int Index;

    public ApplyTo ApplyTo;
}

/// <summary>
/// The 14 operations. Every method here is a pure string transform, which is what makes
/// the preview, the trace and the actual rename provably the same computation.
/// </summary>
public static class StepEngine
{
    private static readonly TimeSpan RegexTimeout = TimeSpan.FromSeconds(2);
    private static readonly Dictionary<string, Regex> RegexCache = new(StringComparer.Ordinal);
    private static readonly object RegexCacheLock = new();
    private static readonly Regex SequenceToken = new(@"\{n:(0+)\}", RegexOptions.CultureInvariant);

    /// <summary>Compiles and caches a pattern; returns null when the pattern does not compile.</summary>
    private static Regex GetRegex(string pattern, RegexOptions options)
    {
        var key = ((int)options).ToString(CultureInfo.InvariantCulture) + "�" + pattern;
        lock (RegexCacheLock)
        {
            if (RegexCache.TryGetValue(key, out var cached)) return cached;
            Regex rx;
            try
            {
                rx = new Regex(pattern, options, RegexTimeout);
            }
            catch (ArgumentException)
            {
                rx = null;
            }
            RegexCache[key] = rx;
            return rx;
        }
    }

    /// <summary>Applies one step in place. Never throws for user-supplied data.</summary>
    public static void Apply(RuleStep step, StepContext ctx)
    {
        switch (step.Op)
        {
            case OpCatalog.OpReplace: ctx.Target = Replace(ctx.Target, step); break;
            case OpCatalog.OpInsert: ctx.Target = Insert(ctx.Target, step); break;
            case OpCatalog.OpRemove: ctx.Target = Remove(ctx.Target, step); break;
            case OpCatalog.OpSequence: ctx.Target = Sequence(ctx.Target, step, ctx.Index); break;
            case OpCatalog.OpCase: ctx.Target = ChangeCase(ctx.Target, step.GetChoice("mode")); break;
            case OpCatalog.OpExtension: ApplyExtension(step, ctx); break;
