            }
        }
        return "{" + token + "}"; // unknown token: kept literally, braces included
    }

    public static string DedupeChars(string s)
    {
        if (s.Length < 2) return s;
        var sb = new StringBuilder(s.Length);
        var prev = '\0';
        var first = true;
        foreach (var c in s)
        {
            if (first || c != prev) sb.Append(c);
            prev = c;
            first = false;
        }
        return sb.ToString();
    }

    private static int Clamp(int value, int min, int max)
    {
        if (max < min) max = min;
        if (value < min) return min;
        if (value > max) return max;
        return value;
    }
}

