namespace BatchRenameStudio.Core;

public static class PlanStatus
{
    public const string Ok = "ok";
    public const string Collision = "collision";
    public const string Unchanged = "unchanged";
    public const string Invalid = "invalid";
}

/// <summary>One entry of the trace: what a single step did to the target string.</summary>
public sealed class TraceEntry
{
    public int Index;
    public string Op;
    public string Before;
    public string After;
}

/// <summary>One file's outcome. Carries both the plan row and its full trace.</summary>
public sealed class PlanItem
{
    public string Original;
    public string Proposed;
    public string Status = PlanStatus.Ok;
    public string Reason = "";
    public List<TraceEntry> Trace = new();

    public bool WillRename => Status == PlanStatus.Ok;
}

public sealed class PlanSummary
{
    public int Total;
    public int Ok;
    public int Collision;
    public int Unchanged;
    public int Invalid;
}

public sealed class PlanResult
{
    public string Directory;
    public List<PlanItem> Items = new();
    public PlanSummary Summary = new();
}

/// <summary>Turns a folder plus a rule set into a plan. Pure computation: nothing is renamed here.</summary>
public static class RenameEngine
{
    /// <summary>
    /// Rule 1 and rule 5: regular files directly inside the folder, ascending by the chosen key.
    /// Time-based sorts break ties by ordinal name so the order is total and therefore deterministic.
    /// </summary>
    public static List<FileInfo> EnumerateFiles(string directory, SortMode sort)
    {
        var dir = new DirectoryInfo(directory);
        var files = new List<FileInfo>(dir.EnumerateFiles("*", SearchOption.TopDirectoryOnly));

        files.Sort((a, b) =>
        {
            int primary;
            switch (sort)
            {
                case SortMode.Created:
                    primary = a.CreationTimeUtc.CompareTo(b.CreationTimeUtc);
                    break;
                case SortMode.Modified:
                    primary = a.LastWriteTimeUtc.CompareTo(b.LastWriteTimeUtc);
                    break;
                default:
                    primary = 0;
                    break;
            }
            return primary != 0 ? primary : string.CompareOrdinal(a.Name, b.Name);
        });

        return files;
    }

    public static PlanResult BuildPlan(string directory, RuleSet rules)
    {
        var steps = rules.ActiveSteps();
        var files = EnumerateFiles(directory, rules.Sort);

        var existing = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var f in files) existing.Add(f.Name);

        var result = new PlanResult { Directory = directory };

        for (var i = 0; i < files.Count; i++)
        {
            result.Items.Add(BuildItem(files[i].Name, rules.ApplyTo, steps, i));
        }

        AssignStatuses(result.Items, existing);

        foreach (var item in result.Items)
        {
            result.Summary.Total++;
            switch (item.Status)
            {
                case PlanStatus.Ok: result.Summary.Ok++; break;
                case PlanStatus.Collision: result.Summary.Collision++; break;
                case PlanStatus.Unchanged: result.Summary.Unchanged++; break;
                case PlanStatus.Invalid: result.Summary.Invalid++; break;
            }
        }

        return result;
    }

    /// <summary>Runs one file through the steps, recording one trace entry per step (rule 4).</summary>
    public static PlanItem BuildItem(string originalName, ApplyTo applyTo, List<RuleStep> steps, int index)
    {
        NameRules.Split(originalName, out var baseName, out var ext);

        var ctx = new StepContext
        {
            Target = applyTo == ApplyTo.Name ? baseName : originalName,
            Ext = ext,
            OriginalExt = ext,
            Index = index,
            ApplyTo = applyTo
        };

        var item = new PlanItem { Original = originalName };

        for (var s = 0; s < steps.Count; s++)
        {
            var before = ctx.Target;
            StepEngine.Apply(steps[s], ctx);
            item.Trace.Add(new TraceEntry
            {
                Index = s,
                Op = steps[s].Op,
                Before = before,
                After = ctx.Target
            });
        }

        item.Proposed = applyTo == ApplyTo.Name ? NameRules.Join(ctx.Target, ctx.Ext) : ctx.Target;
        return item;
    }

    /// <summary>Rule 7, evaluated in the fixed order invalid -&gt; collision -&gt; unchanged -&gt; ok.</summary>
    public static void AssignStatuses(List<PlanItem> items, HashSet<string> existingNames)
    {
        var proposedCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var item in items)
        {
            var key = item.Proposed ?? "";
            proposedCounts.TryGetValue(key, out var n);
            proposedCounts[key] = n + 1;
        }

        foreach (var item in items)
        {
            if (NameRules.IsInvalid(item.Proposed, out var reason))
            {
                item.Status = PlanStatus.Invalid;
                item.Reason = reason;
                continue;
            }

            var clashesWithDisk = existingNames.Contains(item.Proposed) &&
                                  !string.Equals(item.Proposed, item.Original, StringComparison.OrdinalIgnoreCase);
            var clashesWithPlan = proposedCounts.TryGetValue(item.Proposed, out var count) && count > 1;

            if (clashesWithDisk || clashesWithPlan)
            {
                item.Status = PlanStatus.Collision;
                item.Reason = clashesWithPlan
                    ? "another file in this plan proposes the same name"
                    : "a different file with this name already exists";
                continue;
            }

            if (string.Equals(item.Proposed, item.Original, StringComparison.Ordinal))
            {
                item.Status = PlanStatus.Unchanged;
                item.Reason = "";
                continue;
            }

            item.Status = PlanStatus.Ok;
            item.Reason = "";
        }
    }
}

