using System.Text.Encodings.Web;
using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>Serialises the two headless contract documents. UTF-8, no BOM, stable ordering.</summary>
public static class PlanWriter
{
    public const int SchemaVersion = 1;

    private static readonly JsonWriterOptions Options = new()
    {
        Indented = true,
        // File names legitimately contain '&', '+' and non-ASCII letters; the relaxed encoder
        // keeps them readable instead of escaping them to \uXXXX. Still valid JSON either way.
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };

    public static string BuildPlanJson(PlanResult plan)
    {
        using var ms = new MemoryStream();
        using (var w = new Utf8JsonWriter(ms, Options))
        {
            w.WriteStartObject();
            w.WriteNumber("schemaVersion", SchemaVersion);

            w.WriteStartArray("items");
            foreach (var item in plan.Items)
            {
                w.WriteStartObject();
                w.WriteString("original", item.Original);
                w.WriteString("proposed", item.Proposed ?? "");
                w.WriteString("status", item.Status);
                w.WriteString("reason", item.Reason ?? "");
                w.WriteEndObject();
            }
            w.WriteEndArray();

            w.WriteStartObject("summary");
            w.WriteNumber("total", plan.Summary.Total);
            w.WriteNumber("ok", plan.Summary.Ok);
            w.WriteNumber("collision", plan.Summary.Collision);
            w.WriteNumber("unchanged", plan.Summary.Unchanged);
            w.WriteNumber("invalid", plan.Summary.Invalid);
            w.WriteEndObject();

            w.WriteEndObject();
        }
        return JsonIo.Utf8NoBom.GetString(ms.ToArray()) + "\n";
    }

    public static string BuildTraceJson(PlanResult plan)
    {
        using var ms = new MemoryStream();
        using (var w = new Utf8JsonWriter(ms, Options))
        {
            w.WriteStartObject();
            w.WriteNumber("schemaVersion", SchemaVersion);

            w.WriteStartArray("files");
            foreach (var item in plan.Items)
            {
                w.WriteStartObject();
                w.WriteString("original", item.Original);

                w.WriteStartArray("steps");
                foreach (var t in item.Trace)
                {
                    w.WriteStartObject();
                    w.WriteNumber("index", t.Index);
                    w.WriteString("op", t.Op);
                    w.WriteString("before", t.Before ?? "");
                    w.WriteString("after", t.After ?? "");
                    w.WriteEndObject();
                }
                w.WriteEndArray();

                w.WriteString("proposed", item.Proposed ?? "");
                w.WriteString("status", item.Status);
                w.WriteEndObject();
            }
            w.WriteEndArray();

            w.WriteEndObject();
        }
        return JsonIo.Utf8NoBom.GetString(ms.ToArray()) + "\n";
    }

    public static void WritePlan(string path, PlanResult plan) => JsonIo.WriteTextUtf8NoBom(path, BuildPlanJson(plan));

    public static void WriteTrace(string path, PlanResult plan) => JsonIo.WriteTextUtf8NoBom(path, BuildTraceJson(plan));
}

