using System.Globalization;

namespace BatchRenameStudio.Core;

public sealed class RenamePair
{
    public string From;
    public string To;

    public RenamePair(string from, string to)
    {
        From = from;
        To = to;
    }
}

/// <summary>One applied batch, in the form needed to put it back.</summary>
public sealed class RenameBatch
{
    public string Directory;
    public DateTime WhenLocal = DateTime.Now;
    public List<RenamePair> Pairs = new();

    public string Describe() =>
        WhenLocal.ToString("HH:mm:ss", CultureInfo.InvariantCulture) + "  " +
        Pairs.Count.ToString(CultureInfo.InvariantCulture) + " file(s)  in  " + Directory;
}

public sealed class ExecutionReport
{
    public int Renamed;
    public List<string> Errors = new();
    public RenameBatch UndoBatch;
    public bool RolledBack;

    public bool Succeeded => Errors.Count == 0;
}

/// <summary>
/// Performs the renames. Everything goes through a temporary name first, so cycles
/// (a-&gt;b, b-&gt;a) and case-only renames work, and a failure in the middle can be undone.
/// </summary>
public static class RenameExecutor
{
    private const string TempMarker = "__brs_tmp_";

    public static ExecutionReport Apply(string directory, PlanResult plan)
    {
        var pairs = new List<RenamePair>();
        foreach (var item in plan.Items)
        {
            if (item.WillRename) pairs.Add(new RenamePair(item.Original, item.Proposed));
        }
        return Execute(directory, pairs);
    }

    public static ExecutionReport Undo(RenameBatch batch)
    {
        var pairs = new List<RenamePair>(batch.Pairs.Count);
        for (var i = batch.Pairs.Count - 1; i >= 0; i--)
        {
            pairs.Add(new RenamePair(batch.Pairs[i].To, batch.Pairs[i].From));
        }
        return Execute(batch.Directory, pairs);
    }

    private static ExecutionReport Execute(string directory, List<RenamePair> pairs)
    {
        var report = new ExecutionReport();
        if (pairs.Count == 0) return report;

        var staged = new List<RenamePair>(pairs.Count); // temp name -> final name
        var undo = new RenameBatch { Directory = directory };

        // Phase 1: park every source under a unique temporary name.
        var counter = 0;
        foreach (var pair in pairs)
        {
            var tempName = NextTempName(directory, ref counter);
            try
            {
                File.Move(Path.Combine(directory, pair.From), Path.Combine(directory, tempName));
                staged.Add(new RenamePair(tempName, pair.To));
                undo.Pairs.Add(new RenamePair(pair.From, pair.To));
            }
            catch (Exception ex)
            {
                report.Errors.Add("cannot stage '" + pair.From + "': " + ex.Message);
                RollbackStaged(directory, staged, undo, report);
                return report;
            }
        }

        // Phase 2: move each temporary name onto its final name.
        var done = new List<RenamePair>(staged.Count);
        foreach (var pair in staged)
        {
            try
            {
                File.Move(Path.Combine(directory, pair.From), Path.Combine(directory, pair.To));
                done.Add(pair);
                report.Renamed++;
            }
            catch (Exception ex)
            {
                report.Errors.Add("cannot rename to '" + pair.To + "': " + ex.Message);
                // Put the finished ones back to their temp names, then unwind phase 1.
                foreach (var d in done)
                {
                    TryMove(directory, d.To, d.From);
                }
                report.Renamed = 0;
                RollbackStaged(directory, staged, undo, report);
                return report;
            }
        }

        report.UndoBatch = undo;
        return report;
    }

    private static void RollbackStaged(string directory, List<RenamePair> staged, RenameBatch undo, ExecutionReport report)
    {
        for (var i = staged.Count - 1; i >= 0; i--)
        {
            TryMove(directory, staged[i].From, undo.Pairs[i].From);
        }
        report.RolledBack = staged.Count > 0;
        report.UndoBatch = null;
    }

    private static void TryMove(string directory, string from, string to)
    {
        try
        {
            File.Move(Path.Combine(directory, from), Path.Combine(directory, to));
        }
        catch
        {
            // Best effort: the caller already reports the primary failure.
        }
    }

    private static string NextTempName(string directory, ref int counter)
    {
        while (true)
        {
            var name = TempMarker + counter.ToString("0000", CultureInfo.InvariantCulture) + "__";
            counter++;
            if (!File.Exists(Path.Combine(directory, name)) && !Directory.Exists(Path.Combine(directory, name)))
            {
                return name;
            }
        }
    }
}

