using System.Runtime.InteropServices;
using BatchRenameStudio.Cli;
using BatchRenameStudio.Ui;

namespace BatchRenameStudio;

internal static class Program
{
    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool FreeConsole();

    [STAThread]
    private static int Main(string[] args)
    {
        if (args.Length > 0 && HeadlessRunner.IsHeadless(args))
        {
            return HeadlessRunner.Run(args);
        }

        // GUI path: the process is built against the console subsystem so the headless
        // contracts get a real stdout; detach that console before showing any window.
        try
        {
            FreeConsole();
        }
        catch (EntryPointNotFoundException)
        {
            // Not fatal - the console simply stays around.
        }

        var startFolder = args.Length > 0 && Directory.Exists(args[0]) ? args[0] : null;

        Application.EnableVisualStyles();
        Application.SetCompatibleTextRenderingDefault(false);
        Application.SetHighDpiMode(HighDpiMode.SystemAware);
        Application.Run(new MainForm(startFolder));
        return 0;
    }
}

