using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// Property editor for one rule step. The controls are generated from
/// <see cref="OpCatalog"/>, so every operation the engine knows is automatically editable.
/// </summary>
public sealed class StepEditorPanel : Panel
{
    private readonly Label _title = new();
    private readonly Label _summary = new();
    private readonly TableLayoutPanel _table = new();
    private RuleStep _step;
    private bool _suppress;

    /// <summary>Raised after a field was edited (the step is already updated).</summary>
    public event EventHandler StepChanged;

    public StepEditorPanel()
    {
        Padding = new Padding(10, 8, 10, 8);
        AutoScroll = true;

        _title.Dock = DockStyle.Top;
        _title.Height = 24;
        _title.Font = new Font(Font.FontFamily, 10.5F, FontStyle.Bold);
        _title.Text = "No step selected";

        _summary.Dock = DockStyle.Top;
        _summary.Height = 34;
        _summary.ForeColor = Color.FromArgb(90, 90, 90);
        _summary.Text = "Add a step on the left, or pick one to edit its parameters.";

        _table.Dock = DockStyle.Top;
        _table.AutoSize = true;
        _table.AutoSizeMode = AutoSizeMode.GrowAndShrink;
        _table.ColumnCount = 2;
        _table.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 118F));
        _table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100F));
        _table.Padding = new Padding(0, 6, 0, 0);

        // Fill-style member first so the docked headers above win their space.
        Controls.Add(_table);
        Controls.Add(_summary);
        Controls.Add(_title);
    }

    public void Bind(RuleStep step)
    {
        _step = step;
        _suppress = true;
        try
        {
            _table.SuspendLayout();
            _table.Controls.Clear();
            _table.RowStyles.Clear();
            _table.RowCount = 0;

            if (step == null)
            {
                _title.Text = "No step selected";
                _summary.Text = "Add a step on the left, or pick one to edit its parameters.";
                return;
            }

            var spec = step.Spec;
            _title.Text = spec.Title;
            _summary.Text = spec.Summary;

            foreach (var field in spec.Fields)
            {
                AddRow(field, step);
            }

            if (spec.Fields.Length == 0)
            {
                var none = new Label
                {
                    Text = "This operation has no parameters.",
                    ForeColor = Color.FromArgb(110, 110, 110),
                    AutoSize = true,
                    Margin = new Padding(3, 6, 3, 3)
                };
                _table.Controls.Add(none, 0, _table.RowCount);
                _table.SetColumnSpan(none, 2);
                _table.RowCount++;
            }
        }
        finally
        {
            _table.ResumeLayout(true);
            _suppress = false;
        }
    }

    private void AddRow(FieldSpec field, RuleStep step)
    {
        var label = new Label
        {
            Text = field.Label,
            Dock = DockStyle.Fill,
            TextAlign = ContentAlignment.MiddleLeft,
            Margin = new Padding(3, 6, 3, 3)
        };

        Control editor;
        switch (field.Kind)
        {
            case FieldKind.Bool:
            {
                var cb = new CheckBox
                {
                    Checked = step.GetBool(field.Key),
                    AutoSize = true,
                    Margin = new Padding(3, 6, 3, 3),
                    Text = ""
                };
                cb.CheckedChanged += (s, e) => Commit(field.Key, cb.Checked);
                editor = cb;
                break;
            }
            case FieldKind.Int:
            {
                var nud = new NumericUpDown
                {
                    Minimum = field.Min,
                    Maximum = field.Max,
                    Dock = DockStyle.Fill,
                    Margin = new Padding(3, 3, 3, 3)
                };
                var v = step.GetInt(field.Key);
                if (v < field.Min) v = field.Min;
                if (v > field.Max) v = field.Max;
                nud.Value = v;
                nud.ValueChanged += (s, e) => Commit(field.Key, (int)nud.Value);
                editor = nud;
                break;
            }
            case FieldKind.Choice:
            {
                var combo = new ComboBox
                {
                    DropDownStyle = ComboBoxStyle.DropDownList,
                    Dock = DockStyle.Fill,
                    Margin = new Padding(3, 3, 3, 3)
                };
                combo.Items.AddRange(field.Choices);
                combo.SelectedItem = step.GetChoice(field.Key);
                if (combo.SelectedIndex < 0 && combo.Items.Count > 0) combo.SelectedIndex = 0;
                combo.SelectedIndexChanged += (s, e) => Commit(field.Key, combo.SelectedItem as string ?? "");
                editor = combo;
                break;
            }
            default:
            {
                var tb = new TextBox
                {
                    Text = step.GetString(field.Key),
                    Dock = DockStyle.Fill,
                    Margin = new Padding(3, 3, 3, 3)
                };
                tb.TextChanged += (s, e) => Commit(field.Key, tb.Text);
                editor = tb;
                break;
            }
        }

        _table.Controls.Add(label, 0, _table.RowCount);
        _table.Controls.Add(editor, 1, _table.RowCount);
        _table.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        _table.RowCount++;

        if (!string.IsNullOrEmpty(field.Hint))
        {
            var hint = new Label
            {
                Text = field.Hint,
                ForeColor = Color.FromArgb(120, 120, 120),
                AutoSize = true,
                Margin = new Padding(3, 0, 3, 8)
            };
            _table.Controls.Add(hint, 1, _table.RowCount);
            _table.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            _table.RowCount++;
        }
    }

    private void Commit(string key, object value)
    {
        if (_suppress || _step == null) return;
        _step.Set(key, value);
        StepChanged?.Invoke(this, EventArgs.Empty);
    }
}

