using System.Globalization;
using System.Text;
using BatchRenameStudio.Cli;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// The whole GUI: folder + rule set on top, live preview and per-step trace below.
/// The preview is produced by the same <see cref="RenameEngine"/> the headless contracts
/// use, so what the window shows is exactly what --plan would write.
/// </summary>
public sealed class MainForm : Form
{
    private static readonly Color OkColor = Color.FromArgb(0, 110, 40);
    private static readonly Color CollisionColor = Color.FromArgb(180, 30, 30);
    private static readonly Color InvalidColor = Color.FromArgb(190, 100, 0);
    private static readonly Color UnchangedColor = Color.FromArgb(130, 130, 130);

    private RuleSet _ruleSet = new();
