        {
            _ruleSet.ApplyTo = RuleSet.ParseApplyTo(_applyToBox.SelectedItem as string);
            RequestPreview();
        };
        table.Controls.Add(_applyToBox, 4, 0);

        table.Controls.Add(MakeLabel("Sort"), 5, 0);
