        _sortBox.Width = 110;
        _sortBox.Margin = new Padding(3, 1, 3, 3);
        _sortBox.Items.AddRange(new object[] { "name", "created", "modified" });
        _sortBox.SelectedIndexChanged += (s, e) =>
