    {
        _rulesSplit = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Vertical,
            Panel1MinSize = 260,
            Panel2MinSize = 240
        };

        _stepList.View = View.Details;
        _stepList.Dock = DockStyle.Fill;
        _stepList.CheckBoxes = true;
        _stepList.FullRowSelect = true;
        _stepList.MultiSelect = false;
        _stepList.HideSelection = false;
        _stepList.HeaderStyle = ColumnHeaderStyle.Nonclickable;
        _stepList.Columns.Add("Rule steps (unchecked steps are skipped)", 520);
        _stepList.SelectedIndexChanged += (s, e) => OnStepSelectionChanged();
        _stepList.ItemChecked += (s, e) =>
        {
            if (_suppressListEvents) return;
            if (e.Item.Tag is RuleStep step)
            {
