    protected override void OnLoad(EventArgs e)
    {
        base.OnLoad(e);
        TrySetSplitter(_mainSplit, 330);
        TrySetSplitter(_rulesSplit, 470);
        TrySetSplitter(_resultsSplit, 640);
        RefreshPreview();
    }

    private static void TrySetSplitter(SplitContainer split, int distance)
    {
        try
        {
            split.SplitterDistance = distance;
        }
        catch (InvalidOperationException)
        {
            // Window too small for the preferred split; the default is fine.
        }
        catch (ArgumentOutOfRangeException)
        {
        }
    }

    // ------------------------------------------------------------- rule editing

    private void ShowAddMenu(Control anchor)
    {
        _addMenu.Show(anchor, new Point(0, anchor.Height));
    }

    private void AddStep(string op)
    {
        var step = RuleStep.Create(op);
        var at = SelectedStepIndex();
        var insertAt = at < 0 ? _ruleSet.Steps.Count : at + 1;
        _ruleSet.Steps.Insert(insertAt, step);
        RebuildStepList(insertAt);
        RequestPreview();
    }

    private void DuplicateStep()
    {
        var idx = SelectedStepIndex();
        if (idx < 0) return;
        _ruleSet.Steps.Insert(idx + 1, _ruleSet.Steps[idx].Clone());
        RebuildStepList(idx + 1);
        RequestPreview();
    }

    private void RemoveStep()
    {
        var idx = SelectedStepIndex();
        if (idx < 0) return;
        _ruleSet.Steps.RemoveAt(idx);
        RebuildStepList(Math.Min(idx, _ruleSet.Steps.Count - 1));
        RequestPreview();
    }

    private void MoveStep(int delta)
    {
        var idx = SelectedStepIndex();
        if (idx < 0) return;
        var target = idx + delta;
        if (target < 0 || target >= _ruleSet.Steps.Count) return;
        var step = _ruleSet.Steps[idx];
        _ruleSet.Steps.RemoveAt(idx);
        _ruleSet.Steps.Insert(target, step);
        RebuildStepList(target);
        RequestPreview();
    }

    private void ClearSteps()
    {
        if (_ruleSet.Steps.Count == 0) return;
        if (MessageBox.Show(this, "Remove all rule steps?", "Batch Rename Studio Pro",
                MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
        {
            return;
        }
        _ruleSet.Steps.Clear();
        RebuildStepList(-1);
        RequestPreview();
    }

    private int SelectedStepIndex() => _stepList.SelectedIndices.Count > 0 ? _stepList.SelectedIndices[0] : -1;

    private void RebuildStepList(int selectIndex)
    {
        _suppressListEvents = true;
        _stepList.BeginUpdate();
        try
        {
            _stepList.Items.Clear();
            foreach (var step in _ruleSet.Steps)
            {
                var item = new ListViewItem(step.Describe())
                {
                    Tag = step,
                    Checked = step.Enabled,
                    ForeColor = step.Enabled ? SystemColors.WindowText : UnchangedColor
                };
                _stepList.Items.Add(item);
            }
        }
        finally
        {
            _stepList.EndUpdate();
            _suppressListEvents = false;
        }

        if (selectIndex >= 0 && selectIndex < _stepList.Items.Count)
        {
            _stepList.Items[selectIndex].Selected = true;
            _stepList.Items[selectIndex].Focused = true;
            _stepList.EnsureVisible(selectIndex);
        }
        else
        {
            _editor.Bind(null);
        }
    }

    private void OnStepSelectionChanged()
    {
        var idx = SelectedStepIndex();
        _editor.Bind(idx >= 0 && idx < _ruleSet.Steps.Count ? _ruleSet.Steps[idx] : null);
    }

    // ------------------------------------------------------------------ preview

    private void RequestPreview()
    {
        _previewTimer.Stop();
        _previewTimer.Start();
    }

    private void RefreshPreview()
    {
        _previewTimer.Stop();

        var selectedOriginal = SelectedPreviewOriginal();

        if (string.IsNullOrWhiteSpace(_folder) || !Directory.Exists(_folder))
        {
            _plan = null;
            _previewList.Items.Clear();
            _traceList.Items.Clear();
            _statusMain.Text = string.IsNullOrWhiteSpace(_folder) ? "Pick a folder to begin." : "Folder not found: " + _folder;
            _statusCounts.Text = "";
            return;
        }

        try
        {
            _plan = RenameEngine.BuildPlan(_folder, _ruleSet);
        }
        catch (Exception ex)
        {
            _plan = null;
            _previewList.Items.Clear();
            _traceList.Items.Clear();
            _statusMain.Text = "Cannot read folder: " + ex.Message;
            _statusCounts.Text = "";
            return;
        }

        _previewList.BeginUpdate();
        try
        {
            _previewList.Items.Clear();
            foreach (var item in _plan.Items)
            {
                var row = new ListViewItem(item.Original);
                row.SubItems.Add(item.Proposed ?? "");
                row.SubItems.Add(item.Status);
                row.SubItems.Add(item.Reason ?? "");
                row.ForeColor = StatusColor(item.Status);
                row.Tag = item;
                _previewList.Items.Add(row);
            }
        }
        finally
        {
            _previewList.EndUpdate();
        }

        var s = _plan.Summary;
        _statusMain.Text = _folder + "   -   " + _ruleSet.ActiveSteps().Count.ToString(CultureInfo.InvariantCulture) + " active step(s)";
        _statusCounts.Text = "total " + s.Total + "    ok " + s.Ok + "    collision " + s.Collision +
                             "    unchanged " + s.Unchanged + "    invalid " + s.Invalid;

        RestorePreviewSelection(selectedOriginal);
        RefreshTrace();
    }

    private static Color StatusColor(string status) => status switch
    {
        PlanStatus.Ok => OkColor,
        PlanStatus.Collision => CollisionColor,
        PlanStatus.Invalid => InvalidColor,
        _ => UnchangedColor
    };

    private string SelectedPreviewOriginal() =>
        _previewList.SelectedItems.Count > 0 ? _previewList.SelectedItems[0].Text : null;

    private void RestorePreviewSelection(string original)
    {
        if (_previewList.Items.Count == 0) return;
        if (original != null)
        {
            foreach (ListViewItem row in _previewList.Items)
            {
                if (string.Equals(row.Text, original, StringComparison.Ordinal))
                {
                    row.Selected = true;
                    row.EnsureVisible();
                    return;
                }
            }
        }
        _previewList.Items[0].Selected = true;
    }

    private void RefreshTrace()
    {
        _traceList.BeginUpdate();
        try
        {
            _traceList.Items.Clear();
            if (_previewList.SelectedItems.Count == 0 || _previewList.SelectedItems[0].Tag is not PlanItem item)
            {
                _traceHeader.Text = "  Trace - select a file on the left";
                return;
            }

            _traceHeader.Text = "  Trace: " + item.Original + "   ->   " + item.Proposed + "   [" + item.Status + "]";
            foreach (var t in item.Trace)
            {
                var row = new ListViewItem(t.Index.ToString(CultureInfo.InvariantCulture));
                row.SubItems.Add(t.Op);
                row.SubItems.Add(t.Before);
                row.SubItems.Add(t.After);
                if (string.Equals(t.Before, t.After, StringComparison.Ordinal))
                {
                    row.ForeColor = UnchangedColor;
                }
                _traceList.Items.Add(row);
            }
        }
        finally
        {
            _traceList.EndUpdate();
        }
    }

    // ------------------------------------------------------------------ commands

    private void BrowseFolder()
    {
        using var dlg = new FolderBrowserDialog { Description = "Choose the folder to rename in", UseDescriptionForTitle = true };
        if (Directory.Exists(_folder)) dlg.SelectedPath = _folder;
        if (dlg.ShowDialog(this) == DialogResult.OK)
        {
            _folderBox.Text = dlg.SelectedPath;
        }
    }

    private void LoadRules()
    {
        using var dlg = new OpenFileDialog { Filter = "Rule sets (*.json)|*.json|All files (*.*)|*.*", Title = "Load rules" };
        if (dlg.ShowDialog(this) != DialogResult.OK) return;
        try
        {
            _ruleSet = RuleSet.LoadFile(dlg.FileName);
        }
        catch (RuleParseException ex)
        {
            MessageBox.Show(this, ex.Message, "Cannot load rules", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            return;
        }
        _applyToBox.SelectedItem = RuleSet.ApplyToToken(_ruleSet.ApplyTo);
        _sortBox.SelectedItem = RuleSet.SortToken(_ruleSet.Sort);
        RebuildStepList(_ruleSet.Steps.Count > 0 ? 0 : -1);
        RefreshPreview();
        _statusMain.Text = "Loaded " + dlg.FileName;
    }

    private void SaveRules()
    {
        using var dlg = new SaveFileDialog { Filter = "Rule sets (*.json)|*.json", FileName = "rules.json", Title = "Save rules" };
        if (dlg.ShowDialog(this) != DialogResult.OK) return;
        try
        {
            _ruleSet.SaveFile(dlg.FileName);
            _statusMain.Text = "Saved " + dlg.FileName;
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Cannot save rules", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    private void ExportPlan() => ExportDocument("plan.json", (path, plan) => PlanWriter.WritePlan(path, plan));

    private void ExportTrace() => ExportDocument("trace.json", (path, plan) => PlanWriter.WriteTrace(path, plan));

    private void ExportDocument(string defaultName, Action<string, PlanResult> write)
    {
        RefreshPreview();
        if (_plan == null)
        {
            MessageBox.Show(this, "Choose a valid folder first.", "Nothing to export", MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }
        using var dlg = new SaveFileDialog { Filter = "JSON (*.json)|*.json", FileName = defaultName };
        if (dlg.ShowDialog(this) != DialogResult.OK) return;
        try
        {
            write(dlg.FileName, _plan);
            _statusMain.Text = "Wrote " + dlg.FileName;
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Cannot write file", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    private void ApplyRename()
    {
        RefreshPreview();
        if (_plan == null)
        {
            MessageBox.Show(this, "Choose a valid folder first.", "Nothing to do", MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }
        var s = _plan.Summary;
        if (s.Ok == 0)
        {
            MessageBox.Show(this, "No file has a usable new name.", "Nothing to do", MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }

        var message = new StringBuilder();
        message.Append("Rename ").Append(s.Ok).AppendLine(" file(s)?").AppendLine();
        if (s.Collision > 0) message.Append(s.Collision).AppendLine(" file(s) will be skipped: name collision.");
        if (s.Invalid > 0) message.Append(s.Invalid).AppendLine(" file(s) will be skipped: invalid name.");
        if (s.Unchanged > 0) message.Append(s.Unchanged).AppendLine(" file(s) already have the proposed name.");

        if (MessageBox.Show(this, message.ToString(), "Confirm rename", MessageBoxButtons.OKCancel, MessageBoxIcon.Question) != DialogResult.OK)
        {
            return;
        }

        var report = RenameExecutor.Apply(_folder, _plan);
        if (!report.Succeeded)
        {
            var text = string.Join(Environment.NewLine, report.Errors);
            if (report.RolledBack) text += Environment.NewLine + Environment.NewLine + "The batch was rolled back.";
            MessageBox.Show(this, text, "Rename failed", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
        else
        {
            if (report.UndoBatch != null) _undoStack.Push(report.UndoBatch);
            _statusMain.Text = "Renamed " + report.Renamed + " file(s).";
        }
        RefreshPreview();
    }

    private void UndoRename()
    {
        if (_undoStack.Count == 0)
        {
            MessageBox.Show(this, "There is nothing to undo in this session.", "Undo", MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }
        var batch = _undoStack.Peek();
        if (MessageBox.Show(this, "Undo this batch?" + Environment.NewLine + Environment.NewLine + batch.Describe(),
                "Undo", MessageBoxButtons.OKCancel, MessageBoxIcon.Question) != DialogResult.OK)
        {
            return;
        }

        _undoStack.Pop();
        var report = RenameExecutor.Undo(batch);
        if (!report.Succeeded)
        {
            MessageBox.Show(this, string.Join(Environment.NewLine, report.Errors), "Undo failed", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
        else
        {
            _statusMain.Text = "Undid " + report.Renamed + " rename(s).";
        }
        RefreshPreview();
    }

    private void ShowCommandLineHelp()
    {
        MessageBox.Show(this, HeadlessRunner.UsageText(), "Command line", MessageBoxButtons.OK, MessageBoxIcon.Information);
    }

    private void ShowAbout()
    {
        MessageBox.Show(this,
            "Batch Rename Studio Pro 1.0" + Environment.NewLine +
            "C# WinForms on .NET 8, no external packages." + Environment.NewLine + Environment.NewLine +
            "The preview, the trace and the rename all run the same engine," + Environment.NewLine +
            "which is the same engine --plan and --explain use.",
            "About", MessageBoxButtons.OK, MessageBoxIcon.Information);
    }
}

