using System.Globalization;
using System.Text;
using BatchRenameStudio.Cli;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// The whole GUI: folder + rule set on top, live preview and per-step trace below.
/// The preview is produced by the same <see cref="RenameEngine"/> the headless contracts
/// use, so what the window shows is exactly what --plan would write.
/// </summary>
public sealed class MainForm : Form
{
    private static readonly Color OkColor = Color.FromArgb(0, 110, 40);
    private static readonly Color CollisionColor = Color.FromArgb(180, 30, 30);
    private static readonly Color InvalidColor = Color.FromArgb(190, 100, 0);
    private static readonly Color UnchangedColor = Color.FromArgb(130, 130, 130);

    private RuleSet _ruleSet = new();
    private string _folder = "";
    private PlanResult _plan;
    private readonly Stack<RenameBatch> _undoStack = new();
    private bool _suppressListEvents;

    private readonly TextBox _folderBox = new();
    private readonly ComboBox _applyToBox = new();
    private readonly ComboBox _sortBox = new();
    private readonly ListView _stepList = new();
    private readonly StepEditorPanel _editor = new();
    private readonly ListView _previewList = new();
    private readonly ListView _traceList = new();
    private readonly Label _traceHeader = new();
    private readonly ToolStripStatusLabel _statusMain = new();
    private readonly ToolStripStatusLabel _statusCounts = new();
    private readonly System.Windows.Forms.Timer _previewTimer = new();
    private readonly ContextMenuStrip _addMenu = new();

    private SplitContainer _mainSplit;
    private SplitContainer _rulesSplit;
    private SplitContainer _resultsSplit;

    public MainForm(string startFolder)
    {
        Text = "Batch Rename Studio Pro";
        ClientSize = new Size(1240, 820);
        MinimumSize = new Size(960, 640);
        StartPosition = FormStartPosition.CenterScreen;
        Font = new Font("Segoe UI", 9F);

        BuildAddMenu();
        BuildLayout();

        _previewTimer.Interval = 220;
        _previewTimer.Tick += (s, e) =>
        {
            _previewTimer.Stop();
            RefreshPreview();
        };

        _applyToBox.SelectedIndex = 0;
        _sortBox.SelectedIndex = 0;

        if (!string.IsNullOrEmpty(startFolder))
        {
            _folderBox.Text = startFolder;
        }
        else
        {
            _statusMain.Text = "Pick a folder to begin.";
        }
    }

    // ------------------------------------------------------------------ layout

    private void BuildLayout()
    {
        _mainSplit = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Horizontal,
            Panel1MinSize = 180,
            Panel2MinSize = 200
        };

        BuildRulesArea();
        BuildResultsArea();

        var header = BuildHeader();
        var status = BuildStatusStrip();
        var menu = BuildMenu();

        Controls.Add(_mainSplit);
        Controls.Add(status);
        Controls.Add(header);
        Controls.Add(menu);
        MainMenuStrip = menu;
    }

    private Control BuildHeader()
    {
        var table = new TableLayoutPanel
        {
            Dock = DockStyle.Top,
            Height = 42,
            ColumnCount = 8,
            RowCount = 1,
            Padding = new Padding(8, 7, 8, 6)
        };
        table.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100F));
        table.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        table.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        table.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        table.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        table.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        table.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));

        table.Controls.Add(MakeLabel("Folder"), 0, 0);

        _folderBox.Dock = DockStyle.Fill;
        _folderBox.Margin = new Padding(3, 1, 3, 3);
        _folderBox.TextChanged += (s, e) =>
        {
            _folder = _folderBox.Text.Trim().Trim('"');
            RequestPreview();
        };
        table.Controls.Add(_folderBox, 1, 0);

        var browse = new Button { Text = "Browse...", AutoSize = true, Margin = new Padding(3, 0, 12, 3) };
        browse.Click += (s, e) => BrowseFolder();
        table.Controls.Add(browse, 2, 0);

        table.Controls.Add(MakeLabel("Apply to"), 3, 0);
        _applyToBox.DropDownStyle = ComboBoxStyle.DropDownList;
        _applyToBox.Width = 150;
        _applyToBox.Margin = new Padding(3, 1, 12, 3);
        _applyToBox.Items.AddRange(new object[] { "name", "nameAndExtension" });
        _applyToBox.SelectedIndexChanged += (s, e) =>
        {
            _ruleSet.ApplyTo = RuleSet.ParseApplyTo(_applyToBox.SelectedItem as string);
            RequestPreview();
        };
        table.Controls.Add(_applyToBox, 4, 0);

        table.Controls.Add(MakeLabel("Sort"), 5, 0);
        _sortBox.DropDownStyle = ComboBoxStyle.DropDownList;
        _sortBox.Width = 110;
        _sortBox.Margin = new Padding(3, 1, 3, 3);
        _sortBox.Items.AddRange(new object[] { "name", "created", "modified" });
        _sortBox.SelectedIndexChanged += (s, e) =>
        {
            _ruleSet.Sort = RuleSet.ParseSort(_sortBox.SelectedItem as string);
            RequestPreview();
        };
        table.Controls.Add(_sortBox, 6, 0);

        return table;
    }

    private static Label MakeLabel(string text) => new()
    {
        Text = text,
        AutoSize = true,
        Margin = new Padding(3, 6, 6, 3)
    };

    private void BuildRulesArea()
    {
        _rulesSplit = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Vertical,
            Panel1MinSize = 260,
            Panel2MinSize = 240
        };

        _stepList.View = View.Details;
        _stepList.Dock = DockStyle.Fill;
        _stepList.CheckBoxes = true;
        _stepList.FullRowSelect = true;
        _stepList.MultiSelect = false;
        _stepList.HideSelection = false;
        _stepList.HeaderStyle = ColumnHeaderStyle.Nonclickable;
        _stepList.Columns.Add("Rule steps (unchecked steps are skipped)", 520);
        _stepList.SelectedIndexChanged += (s, e) => OnStepSelectionChanged();
        _stepList.ItemChecked += (s, e) =>
        {
            if (_suppressListEvents) return;
            if (e.Item.Tag is RuleStep step)
            {
                step.Enabled = e.Item.Checked;
                e.Item.ForeColor = step.Enabled ? SystemColors.WindowText : UnchangedColor;
                RequestPreview();
            }
        };

        var bar = new FlowLayoutPanel
        {
            Dock = DockStyle.Top,
            Height = 34,
            Padding = new Padding(4, 3, 4, 3),
            AutoSize = false
        };
        bar.Controls.Add(MakeButton("Add step", (s, e) => ShowAddMenu((Control)s)));
        bar.Controls.Add(MakeButton("Duplicate", (s, e) => DuplicateStep()));
        bar.Controls.Add(MakeButton("Remove", (s, e) => RemoveStep()));
        bar.Controls.Add(MakeButton("Up", (s, e) => MoveStep(-1)));
        bar.Controls.Add(MakeButton("Down", (s, e) => MoveStep(1)));
        bar.Controls.Add(MakeButton("Clear", (s, e) => ClearSteps()));

        _rulesSplit.Panel1.Controls.Add(_stepList);
        _rulesSplit.Panel1.Controls.Add(bar);

        _editor.Dock = DockStyle.Fill;
        _editor.StepChanged += (s, e) =>
        {
            var idx = SelectedStepIndex();
            if (idx >= 0 && idx < _stepList.Items.Count)
            {
                _stepList.Items[idx].Text = _ruleSet.Steps[idx].Describe();
            }
            RequestPreview();
        };
        _rulesSplit.Panel2.Controls.Add(_editor);

        _mainSplit.Panel1.Controls.Add(_rulesSplit);
    }

    private static Button MakeButton(string text, EventHandler onClick)
    {
        var b = new Button { Text = text, AutoSize = true, Margin = new Padding(2, 0, 2, 0) };
        b.Click += onClick;
        return b;
    }

    private void BuildResultsArea()
    {
        _resultsSplit = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Vertical,
            Panel1MinSize = 320,
            Panel2MinSize = 260
        };

        _previewList.View = View.Details;
        _previewList.Dock = DockStyle.Fill;
        _previewList.FullRowSelect = true;
        _previewList.MultiSelect = false;
        _previewList.HideSelection = false;
        _previewList.GridLines = false;
        _previewList.Columns.Add("Original", 250);
        _previewList.Columns.Add("Proposed", 250);
        _previewList.Columns.Add("Status", 85);
        _previewList.Columns.Add("Reason", 220);
        _previewList.SelectedIndexChanged += (s, e) => RefreshTrace();

        var previewHeader = new Label
        {
            Dock = DockStyle.Top,
            Height = 22,
            Text = "  Preview - exactly what --plan would write",
            TextAlign = ContentAlignment.MiddleLeft,
            BackColor = Color.FromArgb(240, 240, 240)
        };

        _resultsSplit.Panel1.Controls.Add(_previewList);
        _resultsSplit.Panel1.Controls.Add(previewHeader);

        _traceList.View = View.Details;
        _traceList.Dock = DockStyle.Fill;
        _traceList.FullRowSelect = true;
        _traceList.Columns.Add("#", 34);
        _traceList.Columns.Add("Op", 110);
        _traceList.Columns.Add("Before", 190);
        _traceList.Columns.Add("After", 190);

        _traceHeader.Dock = DockStyle.Top;
        _traceHeader.Height = 22;
        _traceHeader.Text = "  Trace - select a file on the left";
        _traceHeader.TextAlign = ContentAlignment.MiddleLeft;
        _traceHeader.BackColor = Color.FromArgb(240, 240, 240);

        _resultsSplit.Panel2.Controls.Add(_traceList);
        _resultsSplit.Panel2.Controls.Add(_traceHeader);

        var actions = new FlowLayoutPanel
        {
            Dock = DockStyle.Top,
            Height = 36,
            Padding = new Padding(4, 4, 4, 4)
        };
        actions.Controls.Add(MakeButton("Refresh preview (F5)", (s, e) => RefreshPreview()));
        actions.Controls.Add(MakeButton("Apply rename", (s, e) => ApplyRename()));
        actions.Controls.Add(MakeButton("Undo last rename", (s, e) => UndoRename()));
        actions.Controls.Add(MakeButton("Export plan.json", (s, e) => ExportPlan()));
        actions.Controls.Add(MakeButton("Export trace.json", (s, e) => ExportTrace()));

        _mainSplit.Panel2.Controls.Add(_resultsSplit);
        _mainSplit.Panel2.Controls.Add(actions);
    }

    private StatusStrip BuildStatusStrip()
    {
        var strip = new StatusStrip();
        _statusMain.Spring = true;
        _statusMain.TextAlign = ContentAlignment.MiddleLeft;
        _statusCounts.TextAlign = ContentAlignment.MiddleRight;
        strip.Items.Add(_statusMain);
        strip.Items.Add(_statusCounts);
        return strip;
    }

    private MenuStrip BuildMenu()
    {
        var menu = new MenuStrip();

        var file = new ToolStripMenuItem("&File");
        file.DropDownItems.Add(Item("Open &folder...", Keys.Control | Keys.O, (s, e) => BrowseFolder()));
        file.DropDownItems.Add(new ToolStripSeparator());
        file.DropDownItems.Add(Item("&Load rules...", Keys.Control | Keys.L, (s, e) => LoadRules()));
        file.DropDownItems.Add(Item("&Save rules as...", Keys.Control | Keys.S, (s, e) => SaveRules()));
        file.DropDownItems.Add(new ToolStripSeparator());
        file.DropDownItems.Add(Item("Export &plan.json...", Keys.None, (s, e) => ExportPlan()));
        file.DropDownItems.Add(Item("Export &trace.json...", Keys.None, (s, e) => ExportTrace()));
        file.DropDownItems.Add(new ToolStripSeparator());
        file.DropDownItems.Add(Item("E&xit", Keys.Alt | Keys.F4, (s, e) => Close()));
        menu.Items.Add(file);

        var rules = new ToolStripMenuItem("&Rules");
        var add = new ToolStripMenuItem("&Add step");
        foreach (var spec in OpCatalog.All)
        {
            var captured = spec;
            add.DropDownItems.Add(new ToolStripMenuItem(captured.Title + "  -  " + captured.Op, null, (s, e) => AddStep(captured.Op)));
        }
        rules.DropDownItems.Add(add);
        rules.DropDownItems.Add(Item("&Duplicate step", Keys.Control | Keys.D, (s, e) => DuplicateStep()));
        rules.DropDownItems.Add(Item("&Remove step", Keys.None, (s, e) => RemoveStep()));
        rules.DropDownItems.Add(Item("Move &up", Keys.Control | Keys.Up, (s, e) => MoveStep(-1)));
        rules.DropDownItems.Add(Item("Move &down", Keys.Control | Keys.Down, (s, e) => MoveStep(1)));
        rules.DropDownItems.Add(new ToolStripSeparator());
        rules.DropDownItems.Add(Item("&Clear all steps", Keys.None, (s, e) => ClearSteps()));
        menu.Items.Add(rules);

        var actions = new ToolStripMenuItem("&Actions");
        actions.DropDownItems.Add(Item("&Refresh preview", Keys.F5, (s, e) => RefreshPreview()));
        actions.DropDownItems.Add(Item("&Apply rename", Keys.Control | Keys.Enter, (s, e) => ApplyRename()));
        actions.DropDownItems.Add(Item("&Undo last rename", Keys.Control | Keys.Shift | Keys.Z, (s, e) => UndoRename()));
        menu.Items.Add(actions);

        var help = new ToolStripMenuItem("&Help");
        help.DropDownItems.Add(Item("&Command line...", Keys.None, (s, e) => ShowCommandLineHelp()));
        help.DropDownItems.Add(Item("&About", Keys.None, (s, e) => ShowAbout()));
        menu.Items.Add(help);

        return menu;
    }

    private static ToolStripMenuItem Item(string text, Keys shortcut, EventHandler onClick)
    {
        var item = new ToolStripMenuItem(text, null, onClick);
        if (shortcut != Keys.None) item.ShortcutKeys = shortcut;
        return item;
    }

    private void BuildAddMenu()
    {
        foreach (var spec in OpCatalog.All)
        {
            var captured = spec;
            _addMenu.Items.Add(new ToolStripMenuItem(captured.Title + "  -  " + captured.Op, null, (s, e) => AddStep(captured.Op)));
        }
    }

    protected override void OnLoad(EventArgs e)
    {
        base.OnLoad(e);
        TrySetSplitter(_mainSplit, 330);
        TrySetSplitter(_rulesSplit, 470);
        TrySetSplitter(_resultsSplit, 640);
        RefreshPreview();
    }

    private static void TrySetSplitter(SplitContainer split, int distance)
    {
        try
        {
            split.SplitterDistance = distance;
        }
        catch (InvalidOperationException)
        {
            // Window too small for the preferred split; the default is fine.
        }
        catch (ArgumentOutOfRangeException)
        {
        }
    }

    // ------------------------------------------------------------- rule editing

    private void ShowAddMenu(Control anchor)
    {
        _addMenu.Show(anchor, new Point(0, anchor.Height));
    }

    private void AddStep(string op)
    {
        var step = RuleStep.Create(op);
        var at = SelectedStepIndex();
        var insertAt = at < 0 ? _ruleSet.Steps.Count : at + 1;
        _ruleSet.Steps.Insert(insertAt, step);
        RebuildStepList(insertAt);
        RequestPreview();
    }

    private void DuplicateStep()
    {
        var idx = SelectedStepIndex();
        if (idx < 0) return;
        _ruleSet.Steps.Insert(idx + 1, _ruleSet.Steps[idx].Clone());
        RebuildStepList(idx + 1);
        RequestPreview();
    }

    private void RemoveStep()
    {
        var idx = SelectedStepIndex();
        if (idx < 0) return;
        _ruleSet.Steps.RemoveAt(idx);
        RebuildStepList(Math.Min(idx, _ruleSet.Steps.Count - 1));
        RequestPreview();
    }

    private void MoveStep(int delta)
    {
        var idx = SelectedStepIndex();
        if (idx < 0) return;
        var target = idx + delta;
        if (target < 0 || target >= _ruleSet.Steps.Count) return;
        var step = _ruleSet.Steps[idx];
        _ruleSet.Steps.RemoveAt(idx);
        _ruleSet.Steps.Insert(target, step);
        RebuildStepList(target);
        RequestPreview();
    }

    private void ClearSteps()
    {
        if (_ruleSet.Steps.Count == 0) return;
        if (MessageBox.Show(this, "Remove all rule steps?", "Batch Rename Studio Pro",
                MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
        {
            return;
        }
        _ruleSet.Steps.Clear();
        RebuildStepList(-1);
        RequestPreview();
    }

    private int SelectedStepIndex() => _stepList.SelectedIndices.Count > 0 ? _stepList.SelectedIndices[0] : -1;

    private void RebuildStepList(int selectIndex)
    {
        _suppressListEvents = true;
        _stepList.BeginUpdate();
        try
        {
            _stepList.Items.Clear();
            foreach (var step in _ruleSet.Steps)
            {
                var item = new ListViewItem(step.Describe())
                {
                    Tag = step,
                    Checked = step.Enabled,
                    ForeColor = step.Enabled ? SystemColors.WindowText : UnchangedColor
                };
                _stepList.Items.Add(item);
            }
        }
        finally
        {
            _stepList.EndUpdate();
            _suppressListEvents = false;
        }

        if (selectIndex >= 0 && selectIndex < _stepList.Items.Count)
        {
            _stepList.Items[selectIndex].Selected = true;
            _stepList.Items[selectIndex].Focused = true;
            _stepList.EnsureVisible(selectIndex);
        }
        else
        {
            _editor.Bind(null);
        }
    }

    private void OnStepSelectionChanged()
    {
        var idx = SelectedStepIndex();
        _editor.Bind(idx >= 0 && idx < _ruleSet.Steps.Count ? _ruleSet.Steps[idx] : null);
    }

    // ------------------------------------------------------------------ preview

    private void RequestPreview()
    {
        _previewTimer.Stop();
        _previewTimer.Start();
    }

    private void RefreshPreview()
    {
        _previewTimer.Stop();

        var selectedOriginal = SelectedPreviewOriginal();

        if (string.IsNullOrWhiteSpace(_folder) || !Directory.Exists(_folder))
        {
            _plan = null;
            _previewList.Items.Clear();
            _traceList.Items.Clear();
            _statusMain.Text = string.IsNullOrWhiteSpace(_folder) ? "Pick a folder to begin." : "Folder not found: " + _folder;
            _statusCounts.Text = "";
            return;
        }

        try
        {
            _plan = RenameEngine.BuildPlan(_folder, _ruleSet);
        }
        catch (Exception ex)
        {
            _plan = null;
            _previewList.Items.Clear();
            _traceList.Items.Clear();
            _statusMain.Text = "Cannot read folder: " + ex.Message;
            _statusCounts.Text = "";
            return;
        }

        _previewList.BeginUpdate();
        try
        {
            _previewList.Items.Clear();
            foreach (var item in _plan.Items)
            {
                var row = new ListViewItem(item.Original);
                row.SubItems.Add(item.Proposed ?? "");
                row.SubItems.Add(item.Status);
                row.SubItems.Add(item.Reason ?? "");
                row.ForeColor = StatusColor(item.Status);
                row.Tag = item;
                _previewList.Items.Add(row);
            }
        }
        finally
        {
            _previewList.EndUpdate();
        }

        var s = _plan.Summary;
        _statusMain.Text = _folder + "   -   " + _ruleSet.ActiveSteps().Count.ToString(CultureInfo.InvariantCulture) + " active step(s)";
        _statusCounts.Text = "total " + s.Total + "    ok " + s.Ok + "    collision " + s.Collision +
                             "    unchanged " + s.Unchanged + "    invalid " + s.Invalid;

        RestorePreviewSelection(selectedOriginal);
        RefreshTrace();
    }

    private static Color StatusColor(string status) => status switch
    {
        PlanStatus.Ok => OkColor,
        PlanStatus.Collision => CollisionColor,
        PlanStatus.Invalid => InvalidColor,
        _ => UnchangedColor
    };

    private string SelectedPreviewOriginal() =>
        _previewList.SelectedItems.Count > 0 ? _previewList.SelectedItems[0].Text : null;

    private void RestorePreviewSelection(string original)
    {
        if (_previewList.Items.Count == 0) return;
        if (original != null)
        {
            foreach (ListViewItem row in _previewList.Items)
            {
                if (string.Equals(row.Text, original, StringComparison.Ordinal))
                {
                    row.Selected = true;
                    row.EnsureVisible();
                    return;
                }
            }
        }
        _previewList.Items[0].Selected = true;
    }

    private void RefreshTrace()
    {
        _traceList.BeginUpdate();
        try
        {
            _traceList.Items.Clear();
            if (_previewList.SelectedItems.Count == 0 || _previewList.SelectedItems[0].Tag is not PlanItem item)
            {
                _traceHeader.Text = "  Trace - select a file on the left";
                return;
            }

            _traceHeader.Text = "  Trace: " + item.Original + "   ->   " + item.Proposed + "   [" + item.Status + "]";
            foreach (var t in item.Trace)
            {
                var row = new ListViewItem(t.Index.ToString(CultureInfo.InvariantCulture));
                row.SubItems.Add(t.Op);
                row.SubItems.Add(t.Before);
                row.SubItems.Add(t.After);
                if (string.Equals(t.Before, t.After, StringComparison.Ordinal))
                {
                    row.ForeColor = UnchangedColor;
                }
                _traceList.Items.Add(row);
            }
        }
        finally
        {
            _traceList.EndUpdate();
        }
    }

    // ------------------------------------------------------------------ commands

    private void BrowseFolder()
    {
        using var dlg = new FolderBrowserDialog { Description = "Choose the folder to rename in", UseDescriptionForTitle = true };
        if (Directory.Exists(_folder)) dlg.SelectedPath = _folder;
        if (dlg.ShowDialog(this) == DialogResult.OK)
        {
            _folderBox.Text = dlg.SelectedPath;
        }
    }

    private void LoadRules()
    {
        using var dlg = new OpenFileDialog { Filter = "Rule sets (*.json)|*.json|All files (*.*)|*.*", Title = "Load rules" };
        if (dlg.ShowDialog(this) != DialogResult.OK) return;
        try
        {
            _ruleSet = RuleSet.LoadFile(dlg.FileName);
        }
        catch (RuleParseException ex)
        {
            MessageBox.Show(this, ex.Message, "Cannot load rules", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            return;
        }
        _applyToBox.SelectedItem = RuleSet.ApplyToToken(_ruleSet.ApplyTo);
        _sortBox.SelectedItem = RuleSet.SortToken(_ruleSet.Sort);
        RebuildStepList(_ruleSet.Steps.Count > 0 ? 0 : -1);
        RefreshPreview();
        _statusMain.Text = "Loaded " + dlg.FileName;
    }

    private void SaveRules()
    {
        using var dlg = new SaveFileDialog { Filter = "Rule sets (*.json)|*.json", FileName = "rules.json", Title = "Save rules" };
        if (dlg.ShowDialog(this) != DialogResult.OK) return;
        try
        {
            _ruleSet.SaveFile(dlg.FileName);
            _statusMain.Text = "Saved " + dlg.FileName;
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Cannot save rules", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    private void ExportPlan() => ExportDocument("plan.json", (path, plan) => PlanWriter.WritePlan(path, plan));

    private void ExportTrace() => ExportDocument("trace.json", (path, plan) => PlanWriter.WriteTrace(path, plan));

    private void ExportDocument(string defaultName, Action<string, PlanResult> write)
    {
        RefreshPreview();
        if (_plan == null)
        {
            MessageBox.Show(this, "Choose a valid folder first.", "Nothing to export", MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }
        using var dlg = new SaveFileDialog { Filter = "JSON (*.json)|*.json", FileName = defaultName };
        if (dlg.ShowDialog(this) != DialogResult.OK) return;
        try
        {
            write(dlg.FileName, _plan);
            _statusMain.Text = "Wrote " + dlg.FileName;
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Cannot write file", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    private void ApplyRename()
    {
        RefreshPreview();
        if (_plan == null)
        {
            MessageBox.Show(this, "Choose a valid folder first.", "Nothing to do", MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }
        var s = _plan.Summary;
        if (s.Ok == 0)
        {
            MessageBox.Show(this, "No file has a usable new name.", "Nothing to do", MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }

        var message = new StringBuilder();
        message.Append("Rename ").Append(s.Ok).AppendLine(" file(s)?").AppendLine();
        if (s.Collision > 0) message.Append(s.Collision).AppendLine(" file(s) will be skipped: name collision.");
        if (s.Invalid > 0) message.Append(s.Invalid).AppendLine(" file(s) will be skipped: invalid name.");
        if (s.Unchanged > 0) message.Append(s.Unchanged).AppendLine(" file(s) already have the proposed name.");

        if (MessageBox.Show(this, message.ToString(), "Confirm rename", MessageBoxButtons.OKCancel, MessageBoxIcon.Question) != DialogResult.OK)
        {
            return;
        }

        var report = RenameExecutor.Apply(_folder, _plan);
        if (!report.Succeeded)
        {
            var text = string.Join(Environment.NewLine, report.Errors);
            if (report.RolledBack) text += Environment.NewLine + Environment.NewLine + "The batch was rolled back.";
            MessageBox.Show(this, text, "Rename failed", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
        else
        {
            if (report.UndoBatch != null) _undoStack.Push(report.UndoBatch);
            _statusMain.Text = "Renamed " + report.Renamed + " file(s).";
        }
        RefreshPreview();
    }

    private void UndoRename()
    {
        if (_undoStack.Count == 0)
        {
            MessageBox.Show(this, "There is nothing to undo in this session.", "Undo", MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }
        var batch = _undoStack.Peek();
        if (MessageBox.Show(this, "Undo this batch?" + Environment.NewLine + Environment.NewLine + batch.Describe(),
                "Undo", MessageBoxButtons.OKCancel, MessageBoxIcon.Question) != DialogResult.OK)
        {
            return;
        }

        _undoStack.Pop();
        var report = RenameExecutor.Undo(batch);
        if (!report.Succeeded)
        {
            MessageBox.Show(this, string.Join(Environment.NewLine, report.Errors), "Undo failed", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
        else
        {
            _statusMain.Text = "Undid " + report.Renamed + " rename(s).";
        }
        RefreshPreview();
    }

    private void ShowCommandLineHelp()
    {
        MessageBox.Show(this, HeadlessRunner.UsageText(), "Command line", MessageBoxButtons.OK, MessageBoxIcon.Information);
    }

    private void ShowAbout()
    {
        MessageBox.Show(this,
            "Batch Rename Studio Pro 1.0" + Environment.NewLine +
            "C# WinForms on .NET 8, no external packages." + Environment.NewLine + Environment.NewLine +
            "The preview, the trace and the rename all run the same engine," + Environment.NewLine +
            "which is the same engine --plan and --explain use.",
            "About", MessageBoxButtons.OK, MessageBoxIcon.Information);
    }
}

