/// <summary>
/// Applies panel minimums and a preferred splitter position, clamped to what the
/// current window actually allows. A window too small for the preference keeps the
/// framework default instead of throwing.
/// </summary>
private static void ConfigureSplit(SplitContainer split, int min1, int min2, int preferred)
{
    try
    {
        var extent = split.Orientation == Orientation.Vertical ? split.Width : split.Height;
        var usable = extent - split.SplitterWidth;
        if (usable <= 0) return;
        if (min1 + min2 > usable)
        {
            min1 = Math.Max(1, usable / 3);
            min2 = Math.Max(1, usable / 3);
            if (min1 + min2 > usable) return;
        }
        split.Panel1MinSize = min1;
        split.Panel2MinSize = min2;
        var distance = Math.Min(Math.Max(preferred, min1), usable - min2);
        split.SplitterDistance = distance;
    }
    catch (InvalidOperationException)
    {
        // Window too small for the preferred split; the framework default is fine.
    }
    catch (ArgumentOutOfRangeException)
    {
    }
}

