using System.Globalization;
using System.Text;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// The two fixed headless contracts. Both are strictly read-only: they enumerate, compute
/// and write one JSON document, print exactly one summary line to stdout, and exit 0.
/// Anything that goes wrong is reported on stderr with a non-zero exit code.
/// </summary>
public static class HeadlessRunner
{
    public const int ExitOk = 0;
    public const int ExitUsage = 2;
    public const int ExitFailure = 3;

    private enum Mode
    {
        None,
        Plan,
        Explain,
        Apply,
        Help
    }

    /// <summary>True when the command line asks for a headless run (or for help).</summary>
    public static bool IsHeadless(string[] args)
    {
        foreach (var a in args)
        {
            if (a.StartsWith("-", StringComparison.Ordinal)) return true;
        }
        return false;
    }

    public static int Run(string[] args)
    {
        var mode = Mode.None;
        string dir = null;
        string rules = null;
        string outPath = null;
        var confirmed = false;

        for (var i = 0; i < args.Length; i++)
        {
            var a = args[i];
            switch (a)
            {
                case "--plan":
                    if (mode != Mode.None && mode != Mode.Plan) return Usage("--plan, --explain and --apply are mutually exclusive");
                    mode = Mode.Plan;
                    break;
                case "--explain":
                    if (mode != Mode.None && mode != Mode.Explain) return Usage("--plan, --explain and --apply are mutually exclusive");
                    mode = Mode.Explain;
                    break;
                case "--apply":
                    if (mode != Mode.None && mode != Mode.Apply) return Usage("--plan, --explain and --apply are mutually exclusive");
                    mode = Mode.Apply;
                    break;
                case "--yes":
                    confirmed = true;
                    break;
                case "--help":
                case "-h":
                case "-?":
                case "/?":
                    mode = Mode.Help;
                    break;
                case "--dir":
                    if (!TakeValue(args, ref i, out dir)) return Usage("--dir needs a folder path");
                    break;
                case "--rules":
                    if (!TakeValue(args, ref i, out rules)) return Usage("--rules needs a file path");
                    break;
                case "--out":
                    if (!TakeValue(args, ref i, out outPath)) return Usage("--out needs a file path");
                    break;
                default:
                    return Usage("unknown argument '" + a + "'");
            }
        }

        if (mode == Mode.Help)
        {
            Console.Out.Write(UsageText());
            Console.Out.Flush();
            return ExitOk;
        }
        if (mode == Mode.None) return Usage("expected --plan or --explain");
        if (string.IsNullOrWhiteSpace(dir)) return Usage("--dir is required");
        if (string.IsNullOrWhiteSpace(rules)) return Usage("--rules is required");
        if (mode != Mode.Apply && string.IsNullOrWhiteSpace(outPath)) return Usage("--out is required");
        if (mode == Mode.Apply && !confirmed) return Usage("--apply renames files; add --yes to confirm");

        try
        {
            if (!Directory.Exists(dir))
            {
                return Fail("folder not found: " + dir);
            }
            if (!File.Exists(rules))
            {
                return Fail("rules file not found: " + rules);
            }

            var ruleSet = RuleSet.LoadFile(rules);
            var plan = RenameEngine.BuildPlan(dir, ruleSet);

            if (mode == Mode.Plan)
            {
                PlanWriter.WritePlan(outPath, plan);
                var s = plan.Summary;
                WriteSummaryLine(
                    "plan: total=" + s.Total.ToString(CultureInfo.InvariantCulture) +
                    " ok=" + s.Ok.ToString(CultureInfo.InvariantCulture) +
                    " collision=" + s.Collision.ToString(CultureInfo.InvariantCulture) +
                    " unchanged=" + s.Unchanged.ToString(CultureInfo.InvariantCulture) +
                    " invalid=" + s.Invalid.ToString(CultureInfo.InvariantCulture) +
                    " -> " + Path.GetFullPath(outPath));
            }
            else if (mode == Mode.Explain)
            {
                PlanWriter.WriteTrace(outPath, plan);
                var stepCount = 0;
                foreach (var item in plan.Items) stepCount += item.Trace.Count;
                WriteSummaryLine(
                    "explain: files=" + plan.Items.Count.ToString(CultureInfo.InvariantCulture) +
                    " steps=" + stepCount.ToString(CultureInfo.InvariantCulture) +
                    " -> " + Path.GetFullPath(outPath));
            }
            else
            {
                // --apply: the only mode that touches the file system.
                if (!string.IsNullOrWhiteSpace(outPath)) PlanWriter.WritePlan(outPath, plan);
                var report = RenameExecutor.Apply(dir, plan);
                if (!report.Succeeded)
                {
                    foreach (var error in report.Errors) Console.Error.WriteLine("BatchRenameStudio: " + error);
                    if (report.RolledBack) Console.Error.WriteLine("BatchRenameStudio: the batch was rolled back");
                    Console.Error.Flush();
                    return ExitFailure;
                }
                var s2 = plan.Summary;
                WriteSummaryLine(
                    "apply: renamed=" + report.Renamed.ToString(CultureInfo.InvariantCulture) +
                    " skipped=" + (s2.Total - report.Renamed).ToString(CultureInfo.InvariantCulture) +
                    " in " + Path.GetFullPath(dir));
            }
            return ExitOk;
        }
        catch (RuleParseException ex)
        {
            return Fail(ex.Message);
        }
        catch (Exception ex)
        {
            return Fail(ex.GetType().Name + ": " + ex.Message);
        }
    }

    private static bool TakeValue(string[] args, ref int i, out string value)
    {
        if (i + 1 >= args.Length)
        {
            value = null;
            return false;
        }
        i++;
        value = args[i];
        return true;
    }

    private static void WriteSummaryLine(string line)
    {
        Console.Out.Write(line);
        Console.Out.Write(Environment.NewLine);
        Console.Out.Flush();
    }

    private static int Usage(string message)
    {
        Console.Error.WriteLine("BatchRenameStudio: " + message);
        Console.Error.Write(UsageText());
        Console.Error.Flush();
        return ExitUsage;
    }

    private static int Fail(string message)
    {
        Console.Error.WriteLine("BatchRenameStudio: " + message);
        Console.Error.Flush();
        return ExitFailure;
    }

    public static string UsageText()
    {
        var sb = new StringBuilder();
        sb.AppendLine();
        sb.AppendLine("Batch Rename Studio Pro");
        sb.AppendLine();
        sb.AppendLine("  BatchRenameStudio.exe");
        sb.AppendLine("      Start the graphical rule editor.");
        sb.AppendLine();
        sb.AppendLine("  BatchRenameStudio.exe <folder>");
        sb.AppendLine("      Start the editor with <folder> already loaded.");
        sb.AppendLine();
        sb.AppendLine("  BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>");
        sb.AppendLine("      Compute the proposed names and write the plan document. Renames nothing.");
        sb.AppendLine();
        sb.AppendLine("  BatchRenameStudio.exe --explain --dir <folder> --rules <rules.json> --out <trace.json>");
        sb.AppendLine("      Same computation, but records every step's before/after. Renames nothing.");
        sb.AppendLine();
        sb.AppendLine("  BatchRenameStudio.exe --apply --dir <folder> --rules <rules.json> --yes [--out <plan.json>]");
        sb.AppendLine("      Perform the renames. Only files with status \"ok\" are touched.");
        sb.AppendLine("      Without --yes nothing happens. Not part of the fixed contract.");
        sb.AppendLine();
        sb.AppendLine("Exit codes: 0 success, 2 bad usage, 3 runtime failure.");
        sb.AppendLine();
        return sb.ToString();
    }
}

