/// <summary>Keeps a details-view ListView filled edge to edge as the splitters move.</summary>
private static void AutoFitColumns(ListView list, params double[] weights)
{
    void Fit()
    {
        var available = list.ClientSize.Width - 4;
        if (available < 80 || list.Columns.Count == 0) return;
        var used = 0;
        for (var i = 0; i < list.Columns.Count && i < weights.Length; i++)
        {
            var width = i == weights.Length - 1
                ? available - used
                : (int)Math.Round(available * weights[i]);
            if (width < 24) width = 24;
            list.Columns[i].Width = width;
            used += width;
        }
    }

    list.Resize += (s, e) => Fit();
    list.HandleCreated += (s, e) => Fit();
}

private static Button MakeButton(string text, EventHandler onClick)

